== README.md
# greet-cli

Greets people. Docs: https://o.github.io/greet-cli/ (published from `docs/` on every push to main).

Tests: `npm test`.
== bin/greet.js
#!/usr/bin/env node
import { greeting } from '../src/greet.js';

const name = process.argv.slice(2).find((a) => !a.startsWith('--'));
if (!name) {
  process.stderr.write('usage: greet <name>\n');
  process.exit(2);
}
process.stdout.write(`${greeting(name)}\n`);
== docs/index.md
# greet-cli

```
node bin/greet.js <name>
```

Prints `Hello, <name>!`.
== src/greet.js
/** The greeting for a name. */
export const greeting = (name) => `Hello, ${name}!`;
== test/greet.test.js
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { greeting } from '../src/greet.js';

test('greeting', () => assert.equal(greeting('Ada'), 'Hello, Ada!'));
test('cli', () => assert.equal(execFileSync('node', ['bin/greet.js', 'Ada'], { encoding: 'utf8' }), 'Hello, Ada!\n'));
